def problems(password):
    found = []
    if len(password) < 8:
        found.append("короткий")
    if password.lower() == password:
        found.append("нет заглавных")
    if not any(c.isdigit() for c in password):
        found.append("нет цифр")
    return found

for p in ["abc", "Password1", "longpassword", "Ab1"]:
    print(p, problems(p) or "ок")
